SELECT
  c.corporate_number,
  c.company_name,
  a.mail_address,
  a.contact_form,
  a.contact_form_backup
FROM archive_data_companies_contacts a
JOIN data_companies c ON c.corporate_number = a.corporate_number
WHERE a.corporate_number IN (
  3010401097045,5010001086470,6010601048200,7020001077145,2010701025004,
  7140001007718,9010401080763,1180001010995,2010001130058,5010401084611,
  1010001142673,9010001090601,1100001002083,5011101037603,3010401129590,
  9010401018474,1010401054361,9010001030755,6010401096936,6011101062212,
  9020001117832,9180001026514,9010001066543,9030001043648,1013301009245,
  6010601026040,2011101037985,9180001094206,6010001099281,7010001086832,
  3010001048605,3360001002469,9010701004447,8010001117875,2010601035763,
  5020001033661,1010001107305,6110001023140,8013301005238,2013301017998,
  1010001111934,5010001105916,2010401086255,1011101060385,7130001026256,
  8010001077112,3021001047372,7011501010257,9010001102224,2012801000497
)
AND (
  a.contact_form ~* '^https?://'
  OR a.contact_form_backup ~* '^https?://'
)
ORDER BY c.employee_number DESC NULLS LAST;
